<?php $token=htmlspecialchars((string)$csrf,ENT_QUOTES,'UTF-8'); ?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="/assets/css/app.css"><style>
:root{--bg:#f5f6f7;--panel:#fff;--border:#dfe2e5;--text:#343a40;--muted:#6c757d;--accent:#59636d}body{margin:0;background:var(--bg);color:var(--text);font-family:system-ui,-apple-system,Segoe UI,sans-serif}.page{max-width:1050px;margin:auto;padding:28px 18px 48px}.top{display:flex;justify-content:space-between;align-items:center;gap:16px;margin-bottom:20px}.top h1{margin:0 0 5px;font-size:1.7rem}.top p{margin:0}.card{background:var(--panel);border:1px solid var(--border);border-radius:18px;padding:24px;box-shadow:0 8px 30px rgba(30,35,40,.06);margin-bottom:16px}.section-title{font-size:1rem;font-weight:800;margin:0 0 16px}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:15px}label{display:block;font-size:13px;font-weight:700;margin-bottom:6px}input,select{width:100%;box-sizing:border-box;padding:12px;border:1px solid #d5d9dd;border-radius:10px;background:#fff;color:var(--text)}button,.btn{border:0;border-radius:10px;padding:12px 17px;background:#59636d;color:#fff;text-decoration:none;font-weight:750;cursor:pointer}.secondary{background:#eef0f2;color:#343a40;border:1px solid #d6dade}.full{grid-column:1/-1}.muted{color:var(--muted)}.error{color:#b91c1c}.success{color:#047857}.service-toggle{display:flex;align-items:center;gap:10px;margin:0 0 18px;padding:12px 14px;border:1px solid var(--border);border-radius:12px;background:#f7f8f9}.service-toggle input{width:auto}.hidden{display:none!important}.actions{display:flex;align-items:center;gap:10px;flex-wrap:wrap;margin-top:18px}.hint{font-size:12px;color:var(--muted);margin-top:5px}@media(max-width:700px){.grid{grid-template-columns:1fr}.full{grid-column:auto}.top{align-items:flex-start;flex-direction:column}.card{padding:18px}.actions button,.actions a{width:100%;text-align:center;box-sizing:border-box}}
</style><title>Add Customer · ISPLUKA</title></head><body><main class="page"><div class="top"><div><h1>Add Customer</h1><p class="muted">Create the customer account and optionally provision its first Internet service.</p></div><a class="btn secondary" href="/">Dashboard</a></div>
<section class="card"><h2 class="section-title">Customer Information</h2><form id="form"><input type="hidden" name="_csrf" value="<?=$token?>"><div class="grid"><div><label>Customer Code *</label><input name="customer_code" required placeholder="CUS-0001"></div><div><label>Customer Name *</label><input name="name" required></div><div><label>Phone</label><input name="phone" inputmode="tel"></div><div><label>Email</label><input name="email" type="email"></div><div><label>NID</label><input name="nid"></div><div><label>Area</label><input name="area"></div><div class="full"><label>Address</label><input name="address"></div><div><label>Billing Day</label><input name="billing_day" type="number" min="1" max="28" value="1"></div><div><label>Credit Limit</label><input name="credit_limit" type="number" min="0" step="0.01" value="0"></div><div><label>Latitude</label><input name="latitude" type="number" step="any" placeholder="22.3569"></div><div><label>Longitude</label><input name="longitude" type="number" step="any" placeholder="91.7832"></div><div><label>Status</label><select name="status"><option value="active">Active</option><option value="suspended">Suspended</option><option value="closed">Closed</option></select></div><div><label>Reseller ID</label><input name="reseller_id" type="number" min="1" placeholder="Optional"></div></div>
<div class="service-toggle" style="margin-top:20px"><input id="addService" type="checkbox"><label for="addService" style="margin:0">Create first Internet Service now</label></div>
<div id="serviceBox" class="hidden"><h2 class="section-title">First Internet Service</h2><div class="grid"><div><label>Service Type *</label><select name="service_type"><option value="pppoe">PPPoE</option><option value="hotspot">Hotspot</option></select></div><div><label>Package ID</label><input name="package_id" type="number" min="1" placeholder="Optional package ID"></div><div><label>Router ID</label><input name="router_id" type="number" min="1" placeholder="Optional MikroTik router ID"></div><div><label>Username</label><input name="username" placeholder="PPPoE username"></div><div><label>Password / Secret</label><input name="secret" type="password" autocomplete="new-password"></div><div><label>MAC Address</label><input name="mac_address" placeholder="AA:BB:CC:DD:EE:FF"></div><div><label>IP Address</label><input name="ip_address" placeholder="Optional static IP"></div><div><label>Start Date</label><input name="start_date" type="date" value="<?=date('Y-m-d')?>"></div><div><label>Next Billing Date</label><input name="next_billing_date" type="date"></div><div><label>Auto Suspend</label><select name="auto_suspend"><option value="1">Enabled</option><option value="0">Disabled</option></select></div></div><p class="hint">For PPPoE, username is required. Service provisioning is saved only after the customer is created successfully.</p></div>
<div class="actions"><button type="submit">Create Customer</button><a class="btn secondary" href="/customers">Customer List</a></div><p id="msg"></p></form></section></main>
<script>
const f=document.getElementById('form'),m=document.getElementById('msg'),toggle=document.getElementById('addService'),box=document.getElementById('serviceBox');toggle.addEventListener('change',()=>box.classList.toggle('hidden',!toggle.checked));
f.onsubmit=async e=>{e.preventDefault();m.textContent='Creating customer…';m.className='muted';const data=new FormData(f);const r=await fetch('/api/customers',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:new URLSearchParams(data)});let j={};try{j=await r.json()}catch{}if(!r.ok){m.textContent=j.error?.message||'Unable to create customer.';m.className='error';return}const customerId=j.data.id;if(toggle.checked){m.textContent='Customer created. Creating service…';const serviceData=new URLSearchParams();serviceData.set('_csrf',data.get('_csrf'));serviceData.set('customer_id',customerId);['package_id','router_id','service_type','username','secret','mac_address','ip_address','start_date','next_billing_date','auto_suspend'].forEach(k=>{const v=data.get(k);if(v!==null&&v!=='')serviceData.set(k,v)});const sr=await fetch('/api/customer-services',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:serviceData});let sj={};try{sj=await sr.json()}catch{}if(!sr.ok){m.textContent='Customer created (ID '+customerId+'), but service was not created: '+(sj.error?.message||'Unable to create service.');m.className='error';return}m.textContent='Customer and first service created successfully. Customer ID: '+customerId+' · Service ID: '+sj.data.id;m.className='success'}else{m.textContent='Customer created successfully. ID: '+customerId;m.className='success'}f.reset();toggle.checked=false;box.classList.add('hidden');document.querySelector('[name="billing_day"]').value='1';document.querySelector('[name="credit_limit"]').value='0';document.querySelector('[name="status"]').value='active';document.querySelector('[name="start_date"]').value='<?=date('Y-m-d')?>'};
</script></body></html>